### Background
We need storage for idempotency records that map keys to cached responses. Records should expire after a TTL.

### Objective
Create the idempotency repository interface and in-memory implementation.

### Files to Create
- `src/repositories/idempotencyRepository.ts`

### Files to Modify
- `src/repositories/index.ts` (add export)

### Implementation Details
```typescript
// src/repositories/idempotencyRepository.ts

export interface IdempotencyRecord {
  key: string;
  response: unknown;      // The JSON response body
  status_code: number;    // HTTP status code
  created_at: Date;
  expires_at: Date;
}

export interface IIdempotencyRepository {
  get(key: string): Promise<IdempotencyRecord | undefined>;
  set(record: IdempotencyRecord): Promise<void>;
  clear(): Promise<void>;  // For testing
}

const DEFAULT_TTL_MS = 24 * 60 * 60 * 1000; // 24 hours

export class InMemoryIdempotencyRepository implements IIdempotencyRepository {
  private store = new Map<string, IdempotencyRecord>();

  async get(key: string): Promise<IdempotencyRecord | undefined> {
    const record = this.store.get(key);

    // Check if expired
    if (record && record.expires_at < new Date()) {
      this.store.delete(key);
      return undefined;
    }

    return record ? { ...record } : undefined;
  }

  async set(record: IdempotencyRecord): Promise<void> {
    this.store.set(record.key, { ...record });
  }

  async clear(): Promise<void> {
    this.store.clear();
  }
}
```

