import { createIdempotencyMiddleware } from './middleware/index.js';

export const createApp = (options?: {
  accountRepo?: IAccountRepository;
  transactionRepo?: ITransactionRepository;
  idempotencyRepo?: IIdempotencyRepository;  // NEW
}) => {
  const app = new Hono();

  // Initialize repositories
  const accountRepo = options?.accountRepo ?? new InMemoryAccountRepository();
  const transactionRepo = options?.transactionRepo ?? new InMemoryTransactionRepository();
  const idempotencyRepo = options?.idempotencyRepo ?? new InMemoryIdempotencyRepository();  // NEW

  // ... services setup ...

  // Middleware
  app.use('*', logger());

  // Apply idempotency middleware to POST /transactions only
  const idempotencyMiddleware = createIdempotencyMiddleware(idempotencyRepo);
  app.post('/transactions', idempotencyMiddleware);

  // Routes (after middleware)
  app.route('/accounts', createAccountController(accountService));
  app.route('/transactions', createTransactionController(transactionService));

  // ... rest of setup ...
};
```

Note: The middleware must be registered BEFORE the route handler. In Hono, use app.post() with middleware for that specific route.

